#include <bits/stdc++.h>
using namespace std;

int main() {
    int a[600] = {0}, n[600];
    int m, cnt = 0;
    cin >> m;

    for (int i = 0; i < m; ++i) {
        cin >> n[i];
        if (n[i] != 0) {
            a[n[i]]++;
        }
    }

    for (int i = 0; i < 600; ++i) {
        if (a[i] != 0) {
            cnt++;
        }
    }

    cout << cnt + 1;
    return 0;
}

